-- ====================================================
-- 数据表: region_data
-- 数据来源: https://en.wikipedia.org/wiki/ISO_3166-1_alpha-2、https://en.wikipedia.org/wiki/ISO_3166-1_alpha-3、https://docs.paykka.com/zh-hans/payments/docs/developer-resources/currency_fraction_digits、https://en.wikipedia.org/wiki/Currency_symbol、https://en.wikipedia.org/wiki/ISO_4217
-- 共 240 条记录
-- git地址：https://github.com/changdiyixiu/GeoI18n-SQL-Toolkit
-- ====================================================
DROP TABLE if EXISTS `region_data`;
CREATE TABLE IF NOT EXISTS `region_data` (
    `iso2` CHAR(2) NOT NULL COMMENT 'ISO 3166-1 alpha-2 国家代码',
    `iso3` CHAR(3) COMMENT 'ISO 3166-1 alpha-3 国家代码',
    `continent` VARCHAR(30) COMMENT '所属大洲',
    `native_country_name` VARCHAR(200) COMMENT '原生语言国名',
    `country_zh_name` VARCHAR(100) COMMENT '中文国名',
    `country_en_name` VARCHAR(100) COMMENT '英文国名',
    `latitude` DECIMAL(10,7) COMMENT '纬度',
    `longitude` DECIMAL(10,7) COMMENT '经度',
    `phone_code` VARCHAR(20) COMMENT '国际区号',
    `phone_format` VARCHAR(50) COMMENT '电话号码格式',
    `phone_num` INT COMMENT '本地号码位数',
    `capital` VARCHAR(100) COMMENT '首都',
    `tld` VARCHAR(20) COMMENT '顶级域名',
    `flag_emoji` VARCHAR(20) COMMENT '国旗 Emoji',
    `currency_code` VARCHAR(20) COMMENT 'ISO 4217 货币代码',
    `currency_zh_name` VARCHAR(100) COMMENT '货币中文名',
    `currency_en_name` VARCHAR(200) COMMENT '货币英文名',
    `currency_symbol` VARCHAR(20) COMMENT '货币符号',
    `language_code` CHAR(2) COMMENT '主语言 ISO 639-1 代码',
    `native_language_name` VARCHAR(100) COMMENT '原生语言名',
    `language_zh_name` VARCHAR(100) COMMENT '语言中文名',
    `language_en_name` VARCHAR(100) COMMENT '语言英文名',
    `locate_language` JSON COMMENT '全部语言代码数组 JSON',
    `timezones` JSON COMMENT '全部时区信息 JSON 数组',
    PRIMARY KEY (`iso2`),
    KEY (`continent`),
    KEY (`currency_code`),
    KEY (`language_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

